import { useMemo, useState } from 'react'
import { CheckCircle2, Clock3, Play, ShieldAlert, Siren, UserRound, XCircle } from 'lucide-react'

export type ActionState = 'pending' | 'approved' | 'assigned' | 'in_progress' | 'awaiting_revalidation' | 'verified' | 'rejected' | 'deferred'
export type DecisionAction = { actionId: string; decisionId: string; nodeId: string; title: string; owner: string; requestedBy: string; slaHours: number; state: ActionState; riskBefore: number; confidenceBefore: number; priority: number; recommendedAction: string; remediationPlan: string[]; createdAt: string; updatedAt: string; dueAt?: string; version?: number; slaStatus?: 'on_track' | 'at_risk' | 'breached'; escalationLevel?: number; events: { type: string; at: string; actor: string; note?: string }[] }

const stages: { id: ActionState; label: string }[] = [
  { id: 'pending', label: 'Awaiting approval' }, { id: 'approved', label: 'Approved' }, { id: 'assigned', label: 'Owner assigned' }, { id: 'in_progress', label: 'In progress' }, { id: 'awaiting_revalidation', label: 'Re-validation' }, { id: 'verified', label: 'Verified' },
]

export function DecisionActionOrchestration({ action, canAct = true, onTransition }: { action: DecisionAction; canAct?: boolean; onTransition?: (state: ActionState) => void }) {
  const [busy, setBusy] = useState(false)
  const currentIndex = Math.max(0, stages.findIndex((stage) => stage.id === action.state))
  const next = stages[currentIndex + 1]
  const isTerminal = action.state === 'verified' || action.state === 'rejected'
  const delta = useMemo(() => action.riskBefore, [action.riskBefore])
  const slaLabel = action.slaStatus === 'breached' ? 'SLA breached' : action.slaStatus === 'at_risk' ? 'SLA at risk' : 'SLA on track'

  const advance = async (state?: ActionState) => { if (!onTransition || busy) return; setBusy(true); try { await Promise.resolve(onTransition(state ?? next?.id ?? action.state)) } finally { setBusy(false) } }

  return <section className="overflow-hidden rounded-2xl border bg-card"><header className="flex flex-wrap items-center justify-between gap-3 border-b px-5 py-4"><div><div className="text-[10px] font-semibold uppercase tracking-[0.16em] text-muted-foreground">Decision-to-action</div><h3 className="mt-1 flex items-center gap-2 text-lg font-bold"><ShieldAlert className="h-4 w-4 text-primary" /> {action.title}</h3><p className="mt-1 text-xs text-muted-foreground">Turn an approved decision into an owned, time-bound remediation and prove the outcome.</p></div><div className="flex items-center gap-2"><span className="rounded-full border px-2.5 py-1 text-[10px] font-bold uppercase">{action.state.replace(/_/g, ' ')}</span>{action.slaStatus && <span className={`inline-flex items-center gap-1 rounded-full border px-2.5 py-1 text-[10px] font-semibold ${action.slaStatus === 'breached' ? 'text-destructive' : action.slaStatus === 'at_risk' ? '' : 'text-emerald-600'}`}>{action.slaStatus === 'breached' ? <Siren className="h-3 w-3" /> : <Clock3 className="h-3 w-3" />}{slaLabel}</span>}</div></header><div className="grid gap-5 p-5 lg:grid-cols-[1.15fr_.85fr]"><div><div className="flex items-center justify-between"><div className="text-xs font-semibold">Execution lifecycle</div><span className="text-[10px] text-muted-foreground">SLA {action.slaHours}h · Owner {action.owner}</span></div><div className="mt-4 space-y-2">{stages.map((stage, index) => { const done = index < currentIndex || action.state === 'verified'; const active = stage.id === action.state; return <div key={stage.id} className="flex items-center gap-3"><div className={`grid h-8 w-8 shrink-0 place-items-center rounded-full border ${done ? 'border-primary/40 bg-primary/10' : active ? 'border-primary bg-primary/10 ring-4 ring-primary/10' : 'bg-muted/30'}`}>{done ? <CheckCircle2 className="h-4 w-4" /> : <span className="text-[10px] font-bold">{index + 1}</span>}</div><div className={`flex-1 rounded-xl border px-3 py-2 ${active ? 'bg-primary/5' : ''}`}><div className="text-xs font-semibold">{stage.label}</div><div className="mt-0.5 text-[10px] text-muted-foreground">{stage.id === 'in_progress' ? action.recommendedAction : stage.id === 'awaiting_revalidation' ? 'Collect fresh evidence and compare against the baseline.' : stage.id === 'verified' ? 'Close only after evidence-backed verification.' : 'Decision lifecycle checkpoint.'}</div></div></div> })}</div></div><aside className="rounded-2xl border bg-muted/10 p-5"><div className="grid grid-cols-3 gap-2"><Mini label="Risk before" value={delta} /><Mini label="Confidence" value={`${action.confidenceBefore}%`} /><Mini label="Priority" value={action.priority} /></div><div className="mt-5"><div className="flex items-center gap-2 text-xs font-semibold"><UserRound className="h-3.5 w-3.5" /> Ownership</div><div className="mt-2 rounded-xl border bg-background p-3 text-xs"><div className="font-semibold">{action.owner}</div><div className="mt-1 text-[10px] text-muted-foreground">Requested by {action.requestedBy}</div></div></div><div className="mt-4"><div className="flex items-center gap-2 text-xs font-semibold"><Clock3 className="h-3.5 w-3.5" /> SLA / escalation</div><div className="mt-2 rounded-xl border bg-background p-3 text-[10px]"><div className="flex justify-between"><span>Status</span><span className="font-semibold">{slaLabel}</span></div><div className="mt-1 flex justify-between text-muted-foreground"><span>Due</span><span>{action.dueAt ? new Date(action.dueAt).toLocaleString() : '—'}</span></div><div className="mt-1 flex justify-between text-muted-foreground"><span>Escalation level</span><span>{action.escalationLevel ?? 0}</span></div></div></div><div className="mt-4"><div className="flex items-center gap-2 text-xs font-semibold"><Clock3 className="h-3.5 w-3.5" /> Remediation plan</div><div className="mt-2 space-y-1.5">{action.remediationPlan.slice(0, 4).map((step) => <div key={step} className="rounded-lg border bg-background px-3 py-2 text-[10px]">{step}</div>)}</div></div>{canAct && !isTerminal && <div className="mt-5 flex gap-2">{action.state === 'pending' && <button type="button" onClick={() => void advance('approved')} disabled={busy} className="flex-1 rounded-xl bg-primary px-3 py-2.5 text-xs font-semibold text-primary-foreground"><Play className="mr-1 inline h-3.5 w-3.5" /> Approve</button>}{next && action.state !== 'pending' && <button type="button" onClick={() => void advance()} disabled={busy} className="flex-1 rounded-xl bg-primary px-3 py-2.5 text-xs font-semibold text-primary-foreground">Advance →</button>}<button type="button" onClick={() => void advance('deferred')} disabled={busy} className="rounded-xl border px-3 py-2.5 text-xs font-semibold hover:bg-muted">Defer</button></div>}{isTerminal && <div className="mt-5 flex items-center gap-2 rounded-xl border bg-background px-3 py-2 text-[10px]">{action.state === 'verified' ? <CheckCircle2 className="h-4 w-4 text-emerald-600" /> : <XCircle className="h-4 w-4 text-destructive" />} Terminal decision state: {action.state}</div>}</aside></div><footer className="border-t bg-muted/20 px-5 py-3 text-[10px] text-muted-foreground">Workflow events are persistent; SLA escalation is evaluated asynchronously and re-validation remains the proof gate.</footer></section>
}
function Mini({ label, value }: { label: string; value: string | number }) { return <div className="rounded-lg border bg-background px-3 py-2"><div className="text-[9px] uppercase tracking-wider text-muted-foreground">{label}</div><div className="mt-1 text-sm font-bold">{value}</div></div> }
